// Fetch all sources in parallel, return normalized items.
const cfg = $('Config').first().json;
const runType = cfg.runType;
const tickers = cfg.tickers.split(',');
const windowMs = cfg.windowHours * 3600 * 1000;
const now = Date.now();
const since = now - windowMs;
const todayISO = new Date(now).toISOString().slice(0, 10);

const FINNHUB = $env.FINNHUB_API_KEY;
const FRED = $env.FRED_API_KEY;
const EIA = $env.EIA_API_KEY;
const MARKETAUX = $env.MARKETAUX_API_KEY;
const SEC_UA = 'nq-digest hunter547@gmail.com';

const CIK = {
  AAPL: '0000320193', MSFT: '0000789019', NVDA: '0001045810',
  AMZN: '0001018724', META: '0001326801', GOOGL: '0001652044',
  GOOG: '0001652044', AVGO: '0001730168', TSLA: '0001318605',
  COST: '0000909832'
};

const helpers = this.helpers;
async function safeFetch(url, opts = {}) {
  try {
    return await helpers.httpRequest({ method: 'GET', url, headers: opts.headers || {}, json: true, timeout: 15000 });
  } catch (e) { return null; }
}

async function earningsCal() {
  if (!FINNHUB) return [];
  const fromISO = new Date(now - 86400000).toISOString().slice(0, 10);
  const toISO = new Date(now + 3 * 86400000).toISOString().slice(0, 10);
  const j = await safeFetch(`https://finnhub.io/api/v1/calendar/earnings?from=${fromISO}&to=${toISO}&token=${FINNHUB}`);
  if (!j?.earningsCalendar) return [];
  return j.earningsCalendar.filter(e => tickers.includes(e.symbol)).map(e => ({
    source: 'finnhub_earnings',
    external_id: `${e.symbol}_${e.date}_${e.hour}`,
    category: 'earnings',
    ticker: e.symbol,
    title: `${e.symbol} earnings ${e.hour === 'bmo' ? 'pre-market' : e.hour === 'amc' ? 'after-close' : e.date}`,
    body: `EPS est ${e.epsEstimate ?? 'n/a'}, rev est ${e.revenueEstimate ?? 'n/a'}. Actual EPS ${e.epsActual ?? 'pending'}, actual rev ${e.revenueActual ?? 'pending'}.`,
    ts: e.date,
    url: `https://finance.yahoo.com/quote/${e.symbol}`
  }));
}

async function edgarFilings() {
  const out = [];
  for (const [ticker, cik] of Object.entries(CIK)) {
    if (!tickers.includes(ticker)) continue;
    const j = await safeFetch(`https://data.sec.gov/submissions/CIK${cik}.json`, { headers: { 'User-Agent': SEC_UA, 'Accept': 'application/json' } });
    if (!j?.filings?.recent) continue;
    const r = j.filings.recent;
    const edgarSince = now - 5 * 86400000;
    for (let i = 0; i < r.form.length && i < 30; i++) {
      if (r.form[i] !== '8-K') continue;
      const filedAt = new Date(r.filingDate[i]).getTime();
      if (filedAt < edgarSince) continue;
      const accNo = r.accessionNumber[i].replace(/-/g, '');
      out.push({
        source: 'sec_edgar', external_id: r.accessionNumber[i], category: 'earnings', ticker,
        title: `${ticker} 8-K filed ${r.filingDate[i]}`,
        body: r.primaryDocDescription[i] || '8-K filing',
        ts: r.filingDate[i],
        url: `https://www.sec.gov/Archives/edgar/data/${parseInt(cik)}/${accNo}/${r.primaryDocument[i]}`
      });
    }
  }
  return out;
}

async function fredReleases() {
  if (!FRED) return [];
  const series = ['CPIAUCSL', 'PCEPI', 'PAYEMS', 'UNRATE', 'FEDFUNDS', 'GDPC1'];
  const out = [];
  for (const s of series) {
    const j = await safeFetch(`https://api.stlouisfed.org/fred/series/observations?series_id=${s}&api_key=${FRED}&file_type=json&sort_order=desc&limit=2`);
    if (!j?.observations?.length) continue;
    const o = j.observations[0]; const prev = j.observations[1];
    out.push({
      source: 'fred', external_id: `${s}_${o.date}`, category: 'macro', ticker: null,
      title: `${s}: ${o.value} (as of ${o.date})`,
      body: prev ? `Prev ${prev.value} on ${prev.date}` : '',
      ts: o.date, url: `https://fred.stlouisfed.org/series/${s}`
    });
  }
  return out;
}

async function treasuryAuctions() {
  const j = await safeFetch('https://www.treasurydirect.gov/TA_WS/securities/announced?format=json');
  if (!Array.isArray(j)) return [];
  return j.slice(0, 8).map(a => ({
    source: 'treasury', external_id: a.cusip, category: 'macro', ticker: null,
    title: `Treasury auction: ${a.securityType} ${a.securityTerm} on ${a.auctionDate}`,
    body: `Issue ${a.issueDate}, offering ${a.offeringAmount || 'TBA'}`,
    ts: a.auctionDate, url: 'https://www.treasurydirect.gov/auctions/upcoming/'
  }));
}

async function eiaPetroleum() {
  if (!EIA) return [];
  const url = `https://api.eia.gov/v2/petroleum/stoc/wstk/data/?api_key=${EIA}&frequency=weekly&data[0]=value&facets[duoarea][]=NUS&sort[0][column]=period&sort[0][direction]=desc&length=200`;
  const j = await safeFetch(url);
  const rows = j?.response?.data;
  if (!rows?.length) return [];
  const KEY = /^U\.S\. Ending Stocks of (Crude Oil( and Lease Condensate)?|(Total )?(Motor )?Gasoline|Distillate Fuel Oil)$/i;
  const seen = new Set();
  return rows
    .filter(r => KEY.test(r['series-description']))
    .filter(r => { const k = r['series-description']; if (seen.has(k)) return false; seen.add(k); return true; })
    .slice(0, 4)
    .map(r => ({
      source: 'eia', external_id: `${r['series-description']}_${r.period}`, category: 'cross_asset', ticker: null,
      title: `EIA: ${r['series-description']} ${r.period}`,
      body: `${r.value} ${r.units}`,
      ts: r.period, url: 'https://www.eia.gov/petroleum/supply/weekly/'
    }));
}

const NEWS_RELEVANT = /\b(apple|aapl|microsoft|msft|nvidia|nvda|amazon|amzn|meta|alphabet|google|googl|broadcom|avgo|tesla|tsla|costco|cost|netflix|nflx|fed|fomc|powell|rate (cut|hike|decision)|interest rate|inflation|cpi|pce|jobs report|payroll|nonfarm|unemployment|gdp|treasury yield|10-year|nasdaq|qqq|s&p ?500|spx|spy|futures|crude|opec|wti|brent|natural gas|semiconductor|chip(s|maker)|ai (chip|stock|boom|trade)|tariff|trade war|china (trade|export|chip)|sanction|recession|dollar index|dxy|vix|earnings (beat|miss|guidance|outlook)|guidance (cut|raised)|hawkish|dovish|fed minutes|jackson hole|debt ceiling|government shutdown)\b/i;
async function finnhubNews() {
  if (!FINNHUB) return [];
  const j = await safeFetch(`https://finnhub.io/api/v1/news?category=general&token=${FINNHUB}`);
  if (!Array.isArray(j)) return [];
  return j
    .filter(n => n.datetime * 1000 >= since)
    .filter(n => NEWS_RELEVANT.test((n.headline || '') + ' ' + (n.summary || '')))
    .slice(0, 20)
    .map(n => ({
      source: 'finnhub_news', external_id: String(n.id), category: 'news', ticker: null,
      title: n.headline, body: n.summary || '',
      ts: new Date(n.datetime * 1000).toISOString(), url: n.url
    }));
}

async function marketauxNews() {
  if (!MARKETAUX) return [];
  const url = `https://api.marketaux.com/v1/news/all?countries=us&language=en&published_after=${new Date(since).toISOString()}&api_token=${MARKETAUX}&limit=20`;
  const j = await safeFetch(url);
  if (!j?.data) return [];
  return j.data.map(n => ({
    source: 'marketaux', external_id: n.uuid, category: 'news',
    ticker: (n.entities || []).map(e => e.symbol).filter(Boolean).join(',') || null,
    title: n.title, body: n.description || '',
    ts: n.published_at, url: n.url
  }));
}

async function yahooQuotes() {
  const symbols = ['^VIX', '^VVIX', 'DX-Y.NYB', '^TNX', 'NQ=F', 'ES=F'];
  const out = [];
  await Promise.all(symbols.map(async (sym) => {
    const j = await safeFetch(`https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(sym)}?range=2d&interval=1d`, { headers: { 'User-Agent': 'Mozilla/5.0' } });
    const r = j?.chart?.result?.[0];
    if (!r) return;
    const meta = r.meta || {};
    const last = meta.regularMarketPrice;
    const prev = meta.chartPreviousClose ?? meta.previousClose;
    if (last == null) return;
    const pct = (prev && prev !== 0) ? ((last - prev) / prev * 100) : null;
    const name = meta.shortName || meta.longName || sym;
    out.push({
      source: 'yahoo', external_id: `${sym}_${todayISO}_${runType}`, category: 'cross_asset', ticker: sym,
      title: `${name}: ${Number(last).toFixed(2)}${pct !== null ? ` (${pct.toFixed(2)}%)` : ''}`,
      body: `Prev close ${prev != null ? Number(prev).toFixed(2) : 'n/a'}.`,
      ts: new Date((meta.regularMarketTime || Math.floor(Date.now()/1000)) * 1000).toISOString(),
      url: `https://finance.yahoo.com/quote/${encodeURIComponent(sym)}`
    });
  }));
  return out;
}

const results = await Promise.allSettled([earningsCal(), edgarFilings(), fredReleases(), treasuryAuctions(), eiaPetroleum(), finnhubNews(), marketauxNews(), yahooQuotes()]);
const items = results.flatMap(r => r.status === 'fulfilled' ? r.value : []);
return items.map(json => ({ json }));

const items = $('Fetch All Sources').all().map(i => i.json);
const seen = new Set($('Load Seen IDs').all().map(i => i.json.external_id));
const fresh = items.filter(it => !seen.has(it.external_id));
return fresh.map(json => ({ json }));

// Build user prompt asking Claude for STRUCTURED JSON.
const items = $('Fetch All Sources').all().map(i => i.json);
const runType = $('Config').first().json.runType;

const bucket = (cat) => items.filter(i => i.category === cat).slice(0, 30);
const earnings = bucket('earnings');
const macro = bucket('macro');
const news = bucket('news');
const cross = bucket('cross_asset');

const fmt = (arr) => arr.length
  ? arr.map(i => `- [${i.source}${i.ticker ? ' ' + i.ticker : ''}] ${i.title}${i.body ? ' — ' + i.body.slice(0, 280) : ''}`).join('\n')
  : '(none)';

const userPrompt = `You are summarizing market signals for a Nasdaq-100 futures (NQ) trader.
Run: ${runType.toUpperCase()} (${runType === 'premarket' ? '9:15 ET, before US cash open' : '17:45 ET, after US cash close'}).

Return ONLY valid JSON matching this exact shape — no preamble, no markdown fences, no commentary:
{
  "earnings": ["one-line bullet", ...],
  "macro": ["one-line bullet", ...],
  "news": ["one-line bullet", ...],
  "cross_asset": ["one-line bullet", ...],
  "bias_read": "One sentence: net lean for NQ (bullish/bearish/neutral) and the single biggest risk to that lean."
}

Rules: Each bullet is one line, specific with numbers when given, no fluff, no caveats, no disclaimers. If a category has nothing material, return an empty array. The bias_read MUST be a single sentence.

=== EARNINGS ===
${fmt(earnings)}

=== MACRO ===
${fmt(macro)}

=== NEWS ===
${fmt(news)}

=== CROSS-ASSET ===
${fmt(cross)}
`;

return [{ json: { userPrompt, runType, itemCount: items.length } }];

