// Parse Claude's JSON response.
const resp = $input.first().json;
const text = (resp.content || []).map(c => c.text || '').join('\n').trim();
const cleaned = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
let parsed;
try { parsed = JSON.parse(cleaned); }
catch (e) {
  const m = cleaned.match(/\{[\s\S]*\}/);
  parsed = m ? JSON.parse(m[0]) : { earnings: [], macro: [], news: [], cross_asset: [], bias_read: text };
}
for (const k of ['earnings','macro','news','cross_asset']) if (!Array.isArray(parsed[k])) parsed[k] = [];
if (typeof parsed.bias_read !== 'string') parsed.bias_read = '';

const runType = $('Build Prompt').first().json.runType;
const itemCount = $('Build Prompt').first().json.itemCount;
const items = $('Fetch All Sources').all().map(i => i.json);
return [{ json: { ...parsed, runType, itemCount, items } }];

// Build a styled HTML document and emit it as binary for Gotenberg.
const d = $input.first().json;
const { earnings, macro, news, cross_asset, bias_read, runType, itemCount, items } = d;

const dateStr = new Date().toLocaleDateString('en-US', { timeZone: 'America/New_York', weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
const headerLabel = runType === 'premarket' ? 'PRE-MARKET DIGEST' : 'POST-CLOSE DIGEST';
const timeLabel = runType === 'premarket' ? '9:15 AM ET' : '5:45 PM ET';
const esc = (s) => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

const CAT = {
  earnings:    { label: 'Earnings',    color: '#2563eb', bullets: earnings },
  macro:       { label: 'Macro',       color: '#7c3aed', bullets: macro },
  news:        { label: 'News',        color: '#059669', bullets: news },
  cross_asset: { label: 'Cross-Asset', color: '#ea580c', bullets: cross_asset }
};

const summaryCard = (key) => {
  const c = CAT[key];
  if (!c.bullets.length) return '';
  return `<section class="card" style="--accent:${c.color}">
    <header><span class="badge">${c.label}</span><span class="count">${c.bullets.length}</span></header>
    <ul>${c.bullets.map(b => `<li>${esc(b)}</li>`).join('')}</ul>
  </section>`;
};

const itemsByCat = {};
for (const k of Object.keys(CAT)) itemsByCat[k] = items.filter(i => i.category === k);

const rawCard = (key) => {
  const c = CAT[key]; const list = itemsByCat[key];
  if (!list.length) return '';
  return `<section class="raw" style="--accent:${c.color}">
    <h4><span class="dot"></span>${c.label} <span class="n">${list.length} items</span></h4>
    <ul>${list.map(it => `<li>
      <div class="t">${it.ticker ? `<span class="tk">${esc(it.ticker)}</span>` : ''}${esc(it.title)}</div>
      ${it.body ? `<div class="b">${esc(it.body)}</div>` : ''}
      <div class="s">${esc(it.source)}${it.url ? ` · <a href="${esc(it.url)}">link</a>` : ''}</div>
    </li>`).join('')}</ul>
  </section>`;
};

const html = `<!doctype html><html><head><meta charset="utf-8"><title>${headerLabel} — ${esc(dateStr)}</title>
<style>
  @page { size: Letter; margin: 0.55in; }
  * { box-sizing: border-box; }
  html,body { padding:0; margin:0; }
  body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Inter', system-ui, sans-serif; color:#0f172a; line-height:1.45; font-size:10pt; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  .hero { padding:30px 32px 26px; background:linear-gradient(135deg,#0f172a 0%,#1e293b 60%,#312e81 100%); color:#fff; border-radius:16px; margin-bottom:22px; }
  .hero .eyebrow { font-size:9pt; letter-spacing:0.22em; text-transform:uppercase; color:#94a3b8; margin-bottom:10px; font-weight:600; }
  .hero h1 { font-size:28pt; font-weight:800; margin:0; letter-spacing:-0.025em; }
  .hero .sub { margin-top:10px; font-size:10.5pt; color:#cbd5e1; }
  .bias { padding:16px 20px; background:linear-gradient(90deg,#fef3c7 0%,#fde68a 100%); border-left:4px solid #f59e0b; border-radius:10px; margin-bottom:24px; font-size:10.5pt; color:#78350f; }
  .bias .label { font-size:8.5pt; font-weight:700; letter-spacing:0.16em; color:#92400e; text-transform:uppercase; margin-bottom:6px; }
  .bias .text { font-weight:500; line-height:1.5; }
  .section-title { font-size:9.5pt; font-weight:700; letter-spacing:0.18em; text-transform:uppercase; color:#64748b; margin:28px 0 12px; padding-bottom:6px; border-bottom:1px solid #e2e8f0; }
  .grid { display:flex; flex-direction:column; gap:12px; }
  .card { border:1px solid #e2e8f0; border-radius:12px; padding:14px 16px; border-top:3px solid var(--accent); background:#fff; }
  .card header { display:flex; justify-content:space-between; align-items:center; margin-bottom:10px; }
  .card .badge { font-size:9pt; font-weight:700; letter-spacing:0.12em; text-transform:uppercase; color:var(--accent); }
  .card .count { font-size:8pt; color:#64748b; background:#f1f5f9; padding:2px 9px; border-radius:999px; font-weight:600; }
  .card ul { padding-left:18px; margin:0; }
  .card li { margin-bottom:5px; line-height:1.5; }
  .raw { border:1px solid #e2e8f0; border-radius:10px; padding:14px 16px; background:#fff; margin-bottom:10px; }
  .raw h4 { display:flex; align-items:center; gap:8px; font-size:9.5pt; font-weight:700; letter-spacing:0.1em; text-transform:uppercase; color:#0f172a; margin:0 0 10px; }
  .raw h4 .dot { width:8px; height:8px; border-radius:50%; background:var(--accent); display:inline-block; }
  .raw h4 .n { font-size:8pt; color:#94a3b8; font-weight:500; letter-spacing:0; text-transform:none; margin-left:auto; }
  .raw ul { padding:0; margin:0; list-style:none; }
  .raw li { padding:8px 0; border-top:1px solid #f1f5f9; }
  .raw li:first-child { border-top:0; padding-top:0; }
  .raw .t { font-weight:600; font-size:9.5pt; color:#0f172a; }
  .raw .tk { display:inline-block; font-family:'SF Mono',Menlo,monospace; font-size:8pt; font-weight:700; color:var(--accent); background:rgba(0,0,0,0.04); padding:1px 6px; border-radius:4px; margin-right:6px; }
  .raw .b { font-size:9pt; color:#475569; margin-top:3px; }
  .raw .s { font-size:7.5pt; color:#94a3b8; margin-top:4px; font-family:'SF Mono',Menlo,monospace; }
  .raw .s a { color:#94a3b8; text-decoration:none; }
  footer { margin-top:30px; padding-top:14px; border-top:1px solid #e2e8f0; font-size:8pt; color:#94a3b8; text-align:center; letter-spacing:0.05em; }
</style></head><body>
  <div class="hero"><div class="eyebrow">${headerLabel} · ${timeLabel}</div><h1>NQ Futures Daily</h1><div class="sub">${esc(dateStr)}</div></div>
  <div class="bias"><div class="label">Bias Read</div><div class="text">${esc(bias_read || '—')}</div></div>
  <div class="section-title">Summary</div>
  <div class="grid">${['earnings','macro','news','cross_asset'].map(summaryCard).join('')}</div>
  <div class="section-title">Raw Items</div>
  ${['earnings','macro','news','cross_asset'].map(rawCard).join('')}
  <footer>${itemCount} items scanned · generated ${new Date().toISOString().slice(0,16).replace('T',' ')} UTC</footer>
</body></html>`;

const pdfName = `NQ-${runType}-${new Date().toISOString().slice(0,10)}`;
return [{
  json: { runType, biasRead: bias_read, dateStr, headerLabel, pdfName, itemCount },
  binary: { indexHtml: { data: Buffer.from(html).toString('base64'), mimeType: 'text/html', fileName: 'index.html' } }
}];

// Build the short bias-read text message.
const d = $input.first().json;
const esc = (s) => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const header = d.runType === 'premarket' ? 'PRE-MARKET 9:15 ET' : 'POST-CLOSE 17:45 ET';
const dateStr = new Date().toLocaleDateString('en-US', { timeZone: 'America/New_York', month: 'short', day: 'numeric', weekday: 'short' });
const out = `<b>${esc(header)}</b> — ${esc(dateStr)}\n<b>Bias:</b> ${esc(d.bias_read || '—')}`;
return [{ json: { text: out } }];
